# Testing Candidate A: K=4
# We check the 2x2 square defined by coordinates (i, j), (i+1, j), (i, j+1), (i+1, j+1)
# using the coloring function C(i, j) = (i+j) mod 4 + 1.

def get_color(i, j):
    # Map coordinates to colors {1, 2, 3, 4}
    return (i + j) % 4 + 1

def check_2x2(i, j):
    colors = [
        get_color(i, j),
        get_color(i+1, j),
        get_color(i, j+1),
        get_color(i+1, j+1)
    ]
    # Check the number of unique colors
    unique_colors = set(colors)
    return len(unique_colors)

# Test various 2x2 blocks
tests = [(0, 0), (0, 1), (1, 0), (1, 1), (2, 3), (3, 0)]
results = {}
for i, j in tests:
    try:
        k = check_2x2(i, j)
        results[(i, j)] = k
    except IndexError:
        results[(i, j)] = "Out of bounds"

print("Results for 2x2 blocks (i, j):", results)
